import{_ as t,c as a,o as r,a2 as i}from"./chunks/framework.mqLGQ42V.js";const d=JSON.parse('{"title":"监听器 (Listeners) - Rive 编辑器","description":"状态机 (State Machines) 监听器让设计师无需编写代码即可创建交互行为。","frontmatter":{"title":"监听器 (Listeners) - Rive 编辑器","description":"状态机 (State Machines) 监听器让设计师无需编写代码即可创建交互行为。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 监听器"}]]},"headers":[],"relativePath":"editor/state-machine/listeners.md","filePath":"editor/state-machine/listeners.md","lastUpdated":1774838907000}'),n={name:"editor/state-machine/listeners.md"};function s(o,e,l,h,p,g){return r(),a("div",null,[...e[0]||(e[0]=[i('<p>状态机 (State Machines)</p><h1 id="监听器-listeners" tabindex="-1">监听器 (Listeners) <a class="header-anchor" href="#监听器-listeners" aria-label="Permalink to &quot;监听器 (Listeners)&quot;">​</a></h1><p>监听器让设计师无需编写代码即可创建交互行为。</p><p>监听器允许设计师直接在 Rive 内部创建交互行为——如点击、悬停和拖动——无需代码。例如，你可以为一个按钮添加 Pointer Enter、Pointer Exit 和 Click 监听器。当触发时，这些监听器可以更新数据绑定、设置输入、触发事件等，从而在运行时实现动态交互体验。</p><h4 id="​-创建新监听器" tabindex="-1"><a href="#creating-a-new-listener">​</a> 创建新监听器 <a class="header-anchor" href="#​-创建新监听器" aria-label="Permalink to &quot;[​](#creating-a-new-listener) 创建新监听器&quot;">​</a></h4><ol><li>在动画选项卡中，选择你的状态机。</li><li>在监听器选项卡中，点击加号图标。</li></ol><p>如果创建时已选中某个对象，它会自动被指定为目标。 <img src="https://help.rive.app/images/CleanShot2025-06-12at14.46.58.gif" alt="创建监听器"></p><h1 id="​-监听器的组成" tabindex="-1"><a href="#elements-of-a-listener">​</a> 监听器的组成 <a class="header-anchor" href="#​-监听器的组成" aria-label="Permalink to &quot;[​](#elements-of-a-listener) 监听器的组成&quot;">​</a></h1><p>监听器由三部分组成：目标 (Target)、用户动作 (User Action) 和监听器动作 (Listener Action)。</p><h3 id="​-目标-target" tabindex="-1"><a href="#target">​</a> 目标 (Target) <a class="header-anchor" href="#​-目标-target" aria-label="Permalink to &quot;[​](#target) 目标 (Target)&quot;">​</a></h3><p>目标决定在哪里监听用户动作。</p><p><strong>碰撞区域 (Hit Areas)</strong> 目标通常定义响应用户动作的交互区域——类似于游戏开发中的&quot;碰撞盒&quot;。 最佳做法是使用形状作为目标（如透明度为 0 的椭圆或矩形）。如果使用分组，分组内的形状将作为交互区域。 <img src="https://help.rive.app/images/CleanShot2025-06-12at14.52.27.gif" alt="选择目标"></p><p><strong>监听组件上的事件</strong> 将画板或组件设为目标，可以监听从该画板触发的事件。</p><p><strong>不透明目标 (Opaque Target)</strong> 决定指针事件是否会穿透碰撞区域，可能同时触发多个监听器。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.11.08.gif" alt="不透明目标效果"></p><h1 id="​-用户动作-user-action" tabindex="-1"><a href="#user-action">​</a> 用户动作 (User Action) <a class="header-anchor" href="#​-用户动作-user-action" aria-label="Permalink to &quot;[​](#user-action) 用户动作 (User Action)&quot;">​</a></h1><p>用户动作是监听器等待的交互类型。可用动作包括：</p><ul><li><strong>Pointer Down</strong>：鼠标按下或手指按压。</li><li><strong>Pointer Up</strong>：释放鼠标或手指。</li><li><strong>Pointer Enter</strong>：鼠标/手指进入目标区域。</li><li><strong>Pointer Exit</strong>：鼠标/手指离开目标区域。</li><li><strong>Pointer Move</strong>：在目标区域内的任何移动。</li><li><strong>Click</strong>：在同一目标区域内的按下+抬起组合。</li><li><strong>Listen for Event</strong>：仅当目标是画板或组件时可用。</li></ul><h1 id="​-监听器动作-listener-action" tabindex="-1"><a href="#listener-action">​</a> 监听器动作 (Listener Action) <a class="header-anchor" href="#​-监听器动作-listener-action" aria-label="Permalink to &quot;[​](#listener-action) 监听器动作 (Listener Action)&quot;">​</a></h1><p>监听器动作定义用户交互发生时要执行的操作。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.16.20.gif" alt="添加监听器动作"></p><h2 id="​-视图模型更改" tabindex="-1"><a href="#view-model-change">​</a> <strong>视图模型更改</strong> <a class="header-anchor" href="#​-视图模型更改" aria-label="Permalink to &quot;[​](#view-model-change) **视图模型更改**&quot;">​</a></h2><p>更新视图模型实例中的值。这是从 Rive 文件向运行时代码通信的首选方式。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.18.21.gif" alt="视图模型下拉"></p><h3 id="值-vs-属性" tabindex="-1">值 vs 属性 <a class="header-anchor" href="#值-vs-属性" aria-label="Permalink to &quot;值 vs 属性&quot;">​</a></h3><ul><li><strong>Value (值)</strong>：设置为特定值。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.24.51.gif" alt="设置值"></li><li><strong>Property (属性)</strong>：设置为另一个视图模型属性的值。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.31.06.gif" alt="设置属性"></li></ul><p><strong>添加转换器</strong>：可以在属性之间添加转换器（如&quot;加一&quot;转换器）。 <img src="https://help.rive.app/images/CleanShot2025-06-12at15.37.13.gif" alt="转换器示例"></p><h3 id="​-报告事件-report-event" tabindex="-1"><a href="#report-event">​</a> <strong>报告事件 (Report Event)</strong> <a class="header-anchor" href="#​-报告事件-report-event" aria-label="Permalink to &quot;[​](#report-event) **报告事件 (Report Event)**&quot;">​</a></h3><p>每次用户动作触发时发出一个事件。</p><h3 id="​-对齐目标-align-target" tabindex="-1"><a href="#align-target">​</a> <strong>对齐目标 (Align Target)</strong> <a class="header-anchor" href="#​-对齐目标-align-target" aria-label="Permalink to &quot;[​](#align-target) **对齐目标 (Align Target)**&quot;">​</a></h3><p>让目标对象跟随指针位置。可启用&quot;保持偏移&quot;以维持原始距离。</p><h3 id="​-输入更改-input-change" tabindex="-1"><a href="#input-change">​</a> <strong>输入更改 (Input Change)</strong> <a class="header-anchor" href="#​-输入更改-input-change" aria-label="Permalink to &quot;[​](#input-change) **输入更改 (Input Change)**&quot;">​</a></h3><p>允许监听器更改定义的输入——如切换布尔值、触发触发器或设置数字值。</p><p><a href="/docs/editor/state-machine/transitions">过渡 (Transitions)</a><a href="/docs/editor/state-machine/layers">图层 (Layers)</a></p>',31)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
